INSERT INTO `content` VALUES (1,'BOOK','The Lantern of Little Hollow','A shy fox lights the way home for a village that has forgotten how to be brave.','Mira Halloway',6,'BEGINNER','English',18,'/covers/the-lantern-of-little-hollow.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(2,'BOOK','Pip and the Paper Dragon','Pip folds a dragon out of homework and it refuses to stay on the page.','Otis Vance',5,'BEGINNER','English',15,'/covers/pip-and-the-paper-dragon.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(3,'BOOK','The Girl Who Mapped the Rain','Nell charts every puddle in her town and discovers a river nobody remembers.','Ada Rennick',8,'INTERMEDIATE','English',35,'/covers/the-girl-who-mapped-the-rain.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(4,'BOOK','Moonboots','A pair of secondhand boots take Jonah for a walk across the sky.','Sam Okonkwo',7,'BEGINNER','English',22,'/covers/moonboots.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(5,'BOOK','The Clockwork Orchard','Apples that tick, a gardener who cannot sleep, and one very stubborn robin.','Elise Marchetti',9,'INTERMEDIATE','English',48,'/covers/the-clockwork-orchard.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(6,'BOOK','Detective Duckling','A duckling with a magnifying glass solves the case of the missing pond.','Ravi Chandra',6,'BEGINNER','English',20,'/covers/detective-duckling.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(7,'BOOK','Whale Song for Beginners','Two friends learn to speak whale, badly, and make a friend anyway.','Nia Osei',7,'BEGINNER','English',25,'/covers/whale-song-for-beginners.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(8,'BOOK','The Last Library on Mars','When the colony powers down, twelve-year-old Juno keeps the stories running.','Hector Salas',10,'ADVANCED','English',65,'/covers/the-last-library-on-mars.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(9,'BOOK','Grandpa Was a Pirate (Probably)','Every story Grandpa tells gets bigger. This one has a kraken.','Tom Bridger',6,'BEGINNER','English',19,'/covers/grandpa-was-a-pirate-probably.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(10,'BOOK','The Quiet Museum','After closing time the exhibits argue about who has the better century.','Fen Marlowe',9,'INTERMEDIATE','English',44,'/covers/the-quiet-museum.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(11,'BOOK','Bramble Street Detectives','Four neighbours, one stolen trophy, and a very suspicious cat.','Ravi Chandra',9,'INTERMEDIATE','English',52,'/covers/bramble-street-detectives.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(12,'BOOK','How to Grow a Thunderstorm','A funny, careful guide to weather, with experiments you can actually do.','Dr. Yuki Tanabe',8,'INTERMEDIATE','English',40,'/covers/how-to-grow-a-thunderstorm.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(13,'BOOK','The Dinosaur Who Was Late','Trixie the triceratops misses the meteor because she stopped to help a friend.','Otis Vance',5,'BEGINNER','English',14,'/covers/the-dinosaur-who-was-late.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(14,'BOOK','Verses for Very Small Giants','Short, silly poems for people who are bigger on the inside.','Maud Ellery',5,'BEGINNER','English',12,'/covers/verses-for-very-small-giants.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(15,'BOOK','The Keeper of Lost Kites','Every kite that ever escaped ends up in one place, and it needs a librarian.','Mira Halloway',8,'INTERMEDIATE','English',38,'/covers/the-keeper-of-lost-kites.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(16,'BOOK','Signal from the Sixth Moon','A radio built from junk picks up a voice that already knows Ada\'s name.','Hector Salas',11,'ADVANCED','English',70,'/covers/signal-from-the-sixth-moon.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(17,'VIDEO','Storytime: The Lantern of Little Hollow','A narrated read-along of the picture book, with music.','StoryNest Studio',5,'BEGINNER','English',16,'/covers/video-storytime-lantern.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(18,'VIDEO','How Do Volcanoes Work?','An animated tour from magma chamber to eruption, in eight minutes.','StoryNest Studio',8,'INTERMEDIATE','English',8,'/covers/video-how-do-volcanoes-work.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(19,'VIDEO','Meet the Deep Sea','Bioluminescent creatures, explained without the nightmares.','Blue Planet Kids',7,'BEGINNER','English',11,'/covers/video-meet-the-deep-sea.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(20,'VIDEO','Draw a Dragon in 10 Minutes','Follow-along drawing class for beginners. Paper and pencil only.','Studio Pomelo',6,'BEGINNER','English',10,'/covers/video-draw-a-dragon.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(21,'VIDEO','The History of the Alphabet','Where our letters came from, from clay tablets to keyboards.','StoryNest Studio',10,'ADVANCED','English',14,'/covers/video-history-of-the-alphabet.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(22,'VIDEO','Space Station Tour','What a day in orbit actually looks like, hour by hour.','Orbit Academy',9,'INTERMEDIATE','English',18,'/covers/video-space-station-tour.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(23,'VIDEO','Five Experiments With Water','Simple science you can run at the kitchen sink.','Dr. Yuki Tanabe',6,'BEGINNER','English',12,'/covers/video-five-experiments-with-water.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(24,'VIDEO','Bedtime Lullabies','Twenty minutes of calm songs for the end of the day.','StoryNest Studio',3,'BEGINNER','English',20,'/covers/video-bedtime-lullabies.svg',NULL,NULL,2,'2026-11-04 18:13:35'),(25,'BOOK','Ant Country','There is a city under the patio with half a million residents, no mayor, and a rubbish collection better than ours. A guide to what is actually down there.','Dr. Yuki Tanabe',8,'INTERMEDIATE','English',25,'/covers/ant-country.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(26,'BOOK','Detective Marigold and the Missing Marbles','Forty-one marbles have gone from the jar in Class 4B. Marigold Okafor has a notebook, a suspect list, and a growing suspicion that she is on it.','Ravi Chandra',8,'INTERMEDIATE','English',30,'/covers/detective-marigold-and-the-missing-marbles.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(27,'BOOK','Dig Here','A crop mark in a dry August shows a shape in the Harlows\' field. Getting from a shape in the grass to an answer takes two years and a great deal of not digging.','Ravi Chandra',9,'INTERMEDIATE','English',28,'/covers/dig-here.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(28,'BOOK','Every Owl in the Wood','Ned is allowed to stay up until nine if he is counting owls. He has counted one owl, eleven times, and he is beginning to suspect something.','Mira Halloway',6,'BEGINNER','English',14,'/covers/every-owl-in-the-wood.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(29,'BOOK','Four Hundred Steps Down','The cave under Harrow Fell has been mapped to four hundred metres. Wren is part of the team that finds out what is past the sump.','Hector Salas',10,'ADVANCED','English',35,'/covers/four-hundred-steps-down.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(30,'BOOK','Fox and the Fox-Shaped Hole','There is a fox-shaped hole in the hedge at the end of the garden, and a fox who has grown too big for it, and a decision that has to be made about both.','Mira Halloway',6,'BEGINNER','English',15,'/covers/fox-and-the-fox-shaped-hole.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(31,'BOOK','Letters to the Far North','Class 5 writes to a weather station eleven hundred miles north. Only one person writes back, and she writes to Dayo.','Nia Osei',9,'INTERMEDIATE','English',27,'/covers/letters-to-the-far-north.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(32,'BOOK','The Lighthouse That Forgot to Sleep','The lamp at Gull Point has not gone dark in eleven days, and only Tess has noticed that it is frightened of the morning.','Mira Halloway',6,'BEGINNER','English',18,'/covers/lighthouse-that-forgot-to-sleep.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(33,'BOOK','Mabel and the Midnight Market','Between the last bus and the first milk float there is a market that sells things nobody has invented yet, and Mabel has just been handed a stall of her own.','Fen Marlowe',8,'INTERMEDIATE','English',34,'/covers/mabel-and-the-midnight-market.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(34,'BOOK','Mo and the Mountain of Homework','Mo has eleven pieces of homework, four days, and a plan involving a wall chart that nobody believes will work.','Tom Bridger',7,'BEGINNER','English',16,'/covers/mo-and-the-mountain-of-homework.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(35,'BOOK','Mountain Rescue','A walker is missing on Harrow Fell in November. Tam has been on the rescue team for three weeks and is about to learn what the job actually is.','Nia Osei',10,'ADVANCED','English',38,'/covers/mountain-rescue.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(36,'BOOK','My Grandfather\'s Bicycle','The bicycle in the shed is seventy years old, has no gears, and carried a man four thousand miles. Rafi is going to make it work again.','Sam Okonkwo',9,'INTERMEDIATE','English',28,'/covers/my-grandfathers-bicycle.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(37,'BOOK','Nell Finds the Ninth Moon','The survey says Kepler-62 has eight moons. Nell has counted nine for three months, and the only person who believes her is the one who taught her to count.','Hector Salas',10,'ADVANCED','English',46,'/covers/nell-finds-the-ninth-moon.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(38,'BOOK','Ninety Seconds','Dari can swim the 100 metres in ninety seconds and has done for two years. The reason he is stuck has nothing to do with how hard he trains.','Nia Osei',10,'ADVANCED','English',36,'/covers/ninety-seconds.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(39,'BOOK','Nobody\'s Dog','The brown dog belongs to the whole of Fen Street and to none of it, and when the council letter arrives, eleven houses have to decide what that means.','Sam Okonkwo',7,'BEGINNER','English',18,'/covers/nobodys-dog.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(40,'BOOK','Ollie and the Ocean of Jars','Ollie\'s great-aunt keeps the sea in jars on a shelf, one for every day she swam in it, and today she has asked Ollie to open one.','Nia Osei',6,'BEGINNER','English',17,'/covers/ollie-and-the-ocean-of-jars.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(41,'BOOK','Paper Boats','Every Sunday Ama and her father fold one paper boat and put it on the stream. This Sunday her father is not there, and Ama folds one anyway.','Maud Ellery',5,'BEGINNER','English',12,'/covers/paper-boats.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(42,'BOOK','Robot Gardener','Unit Nine was built to keep the allotment perfectly tidy, and it is extremely good at it, which is how it very nearly kills everything.','Otis Vance',7,'BEGINNER','English',17,'/covers/robot-gardener.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(43,'BOOK','Rocket Jam','Priya builds a rocket out of a wheelie bin and a great deal of optimism, and gets exactly as far as the end of the garden, which turns out to be far enough.','Otis Vance',7,'BEGINNER','English',20,'/covers/rocket-jam.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(44,'BOOK','Seeds from the Attic','There are eleven paper packets of seed in the attic, labelled in 1947. Niamh wants to know whether any of them are still alive.','Ada Rennick',8,'INTERMEDIATE','English',23,'/covers/seeds-from-the-attic.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(45,'BOOK','Small Poems for Loud Days','Twenty short poems for days that are too big: too noisy, too fast, too full of other people.','Maud Ellery',5,'BEGINNER','English',13,'/covers/small-poems-for-loud-days.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(46,'BOOK','Soup for Forty','The church hall makes soup for forty every Wednesday. This Wednesday there are sixty-one people and Ife is in charge of the pot.','Elise Marchetti',6,'BEGINNER','English',15,'/covers/soup-for-forty.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(47,'BOOK','Sprocket Learns to Wait','The hospital robot is very good at being useful and very bad at being still, and the boy in bay four needs the second thing far more than the first.','Hector Salas',9,'INTERMEDIATE','English',32,'/covers/sprocket-learns-to-wait.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(48,'BOOK','Starling City','Forty thousand starlings arrive over the pier at dusk and fly as one thing. Nobody is leading them. Here is what is actually happening.','Dr. Yuki Tanabe',8,'INTERMEDIATE','English',24,'/covers/starling-city.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(49,'BOOK','The Bakery at the Bottom of the Hill','Grandad has forgotten the recipe he has made every Sunday for fifty years, and Tam is the only one who thinks it can be found again.','Elise Marchetti',7,'BEGINNER','English',22,'/covers/the-bakery-at-the-bottom-of-the-hill.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(50,'BOOK','The Bee That Would Not Dance','Every bee that finds flowers comes home and dances the directions. Bee Forty-One found the best flowers in the valley and would not dance at all.','Ada Rennick',7,'BEGINNER','English',17,'/covers/the-bee-that-would-not-dance.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(51,'BOOK','The Boy Who Counted Clouds','Tomas counts everything, until the day he tries to count the sky and finds out what numbers are actually for.','Maud Ellery',5,'BEGINNER','English',14,'/covers/the-boy-who-counted-clouds.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(52,'BOOK','The Boy Who Heard Colours','To Idris, a trumpet is orange and a cello is dark green, and he assumed everyone knew that until the day he said it out loud.','Elise Marchetti',7,'BEGINNER','English',20,'/covers/the-boy-who-heard-colours.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(53,'BOOK','The Bridge That Took Nine Years','The Forth Bridge took nine years, cost the lives of dozens of men, and was built in the shadow of the worst bridge disaster in British history. This is why it looks the way it does.','Dr. Yuki Tanabe',10,'ADVANCED','English',37,'/covers/the-bridge-that-took-nine-years.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(54,'BOOK','The Cake That Took All Day','Pim is making a cake for his sister entirely on his own, and it is going to take eleven hours and four disasters.','Elise Marchetti',6,'BEGINNER','English',14,'/covers/the-cake-that-took-all-day.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(55,'BOOK','The Cat Who Sat on the Map','The expedition has nine members, four hundred miles to cross, and one cat who will not get off the only map they have.','Tom Bridger',6,'BEGINNER','English',16,'/covers/the-cat-who-sat-on-the-map.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(56,'BOOK','The Clockmaker\'s Apprentice','The town clock has run fast by four minutes a day for ninety years, and every clockmaker who has tried to fix it has made it worse. Lira is the eleventh.','Elise Marchetti',9,'INTERMEDIATE','English',33,'/covers/the-clockmakers-apprentice.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(57,'BOOK','The Dragon Who Was Scared of Fire','Ember is a perfectly good dragon in every respect except the important one, and the kingdom has a bonfire to light on Saturday.','Otis Vance',6,'BEGINNER','English',15,'/covers/the-dragon-who-was-scared-of-fire.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(58,'BOOK','The Girl Who Drew the River','Bea drew the same bend of the river every week for a year. The drawings turned out to be evidence.','Ada Rennick',8,'INTERMEDIATE','English',26,'/covers/the-girl-who-drew-the-river.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(59,'BOOK','The Girl Who Fixed the Weather','The village has been promised rain for eleven days running and has had none. Wren decides that if nobody else will check the forecast, she will.','Dr. Yuki Tanabe',8,'INTERMEDIATE','English',26,'/covers/the-girl-who-fixed-the-weather.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(60,'BOOK','The Girl Who Talked to Trains','Every train that passes the end of Immy\'s garden has something to say, and the 8:14 has been saying the same worrying thing for a week.','Sam Okonkwo',7,'BEGINNER','English',19,'/covers/the-girl-who-talked-to-trains.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(61,'BOOK','The Girl Who Was Good at Losing','Esi has lost forty-one chess games in a row on purpose, and the club has no idea what she is doing.','Ravi Chandra',8,'INTERMEDIATE','English',22,'/covers/the-girl-who-was-good-at-losing.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(62,'BOOK','The Girl With the Loudest Laugh','Bea has been told to be quieter by eleven different adults, and then she is put next to a boy who has not spoken in school for a year.','Otis Vance',7,'BEGINNER','English',16,'/covers/the-girl-with-the-loudest-laugh.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(63,'BOOK','The Great Pancake Robbery','Forty-two pancakes went missing from the village hall between nine and ten in the morning, and Nish intends to find out exactly how.','Ravi Chandra',7,'BEGINNER','English',18,'/covers/the-great-pancake-robbery.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(64,'BOOK','The House That Was Older Than the Town','Number Four Crow Lane is on no map before 1890 and on every map after. Esme wants to know where it was for the three hundred years in between.','Fen Marlowe',9,'INTERMEDIATE','English',30,'/covers/the-house-that-was-older-than-the-town.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(65,'BOOK','The Inventor of Nothing','Great-Uncle Bertie has eleven patents and has never sold one. Suri goes through the lot of them and finds that one of them already exists, in every house in the country.','Fen Marlowe',8,'INTERMEDIATE','English',23,'/covers/the-inventor-of-nothing.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(66,'BOOK','The Island That Wasn\'t There','Sable Island appears on charts from 1814 to 1976 and has never existed. Teo wants to know who put it there and why it took a hundred and sixty years to remove.','Hector Salas',9,'INTERMEDIATE','English',31,'/covers/the-island-that-wasnt-there.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(67,'BOOK','The Last Day of the Pier','The pier at Thwaite closes on the thirtieth of September after a hundred and four years. Lev spends the last day writing down what was there.','Elise Marchetti',9,'INTERMEDIATE','English',26,'/covers/the-last-day-of-the-pier.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(68,'BOOK','The Last Dinosaur in the Garden','There is a dinosaur under the apple tree. She is four centimetres long, she is extremely cross about it, and Dev is the only one who will take her seriously.','Otis Vance',6,'BEGINNER','English',16,'/covers/the-last-dinosaur-in-the-garden.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(69,'BOOK','The Last Race of the Season','Kaya has come second to the same rider eleven times. On the twelfth, she finds out why, and it is not about legs.','Nia Osei',9,'INTERMEDIATE','English',27,'/covers/the-last-race-of-the-season.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(70,'BOOK','The Last Train to Nowhere','The timetable at Thwaite lists a 23:47 service to a station that closed in 1964. It has been printed every year for sixty-one years and Ines wants to know why.','Fen Marlowe',9,'INTERMEDIATE','English',29,'/covers/the-last-train-to-nowhere.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(71,'BOOK','The Longest Night of the Year','On the shortest day, the village lights one candle in every window. This year there is a window with nobody behind it, and Senna has noticed.','Mira Halloway',7,'BEGINNER','English',18,'/covers/the-longest-night-of-the-year.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(72,'BOOK','The Mountain That Grew Overnight','In 1943 a farmer in Mexico watched a crack in his cornfield become a volcano four hundred metres tall. This is what happened, and how we know.','Dr. Yuki Tanabe',9,'INTERMEDIATE','English',38,'/covers/the-mountain-that-grew-overnight.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(73,'BOOK','The Museum of Ordinary Things','The town museum has three Roman coins and no visitors. Ola proposes exhibiting a bus ticket, a shoelace and a jar of buttons, and the trouble starts there.','Fen Marlowe',8,'INTERMEDIATE','English',24,'/covers/the-museum-of-ordinary-things.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(74,'BOOK','The Night the Lights Went Out','The power goes off at six o\'clock on the coldest night of the year, and Lola discovers her family is much better at this than she expected.','Mira Halloway',6,'BEGINNER','English',15,'/covers/the-night-the-lights-went-out.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(75,'BOOK','The Politest Pirate','Captain Bartholomew Nibbs would like to rob your ship, if that is convenient, and has brought a form for you to fill in.','Tom Bridger',7,'BEGINNER','English',19,'/covers/the-politest-pirate.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(76,'BOOK','The Queen Who Lost Her Voice','The Queen of Ravenshold wakes with no voice at all on the morning of the longest speech of the year, and the kingdom discovers it can hear her anyway.','Maud Ellery',6,'BEGINNER','English',16,'/covers/the-queen-who-lost-her-voice.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(77,'BOOK','The Quietest Goal','Toma is the worst player on the worst team in the league, and he has worked out the one job on the pitch that nobody else wants to do.','Sam Okonkwo',7,'BEGINNER','English',16,'/covers/the-quietest-goal.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(78,'BOOK','The Shop That Sold Rain','There is a shop on Caddis Lane that sells weather by the bottle, and Juno has saved up eleven weeks to buy one afternoon of rain.','Mira Halloway',7,'BEGINNER','English',17,'/covers/the-shop-that-sold-rain.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(79,'BOOK','The Snow Fox of Silver Wood','Everyone in the village has seen the white fox once. Jonah has seen her eleven times, and he has worked out that she is not lucky at all — she is lost.','Nia Osei',8,'INTERMEDIATE','English',28,'/covers/the-snow-fox-of-silver-wood.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(80,'BOOK','The Wrong Kind of Magic','Every child at Ravenhill gets one spell on their ninth birthday. Wes gets the ability to make small objects slightly warmer, and the school has no idea what to do with him.','Fen Marlowe',8,'INTERMEDIATE','English',25,'/covers/the-wrong-kind-of-magic.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(81,'BOOK','Three Hundred Sheep','Gathering a fell takes nine people, four dogs and a whole day. Erin is allowed to come for the first time, and is given the job nobody wants.','Ada Rennick',8,'INTERMEDIATE','English',24,'/covers/three-hundred-sheep.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(82,'BOOK','Thunder and the Thing in the Hay','The biggest horse on the farm will not go into the barn, and everyone says he is being difficult. Rosa thinks he is being clear.','Tom Bridger',7,'BEGINNER','English',18,'/covers/thunder-and-the-thing-in-the-hay.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(83,'BOOK','Twelve Hours in the Desert','The truck breaks down ninety miles from anywhere at six in the morning. What Sol does in the next twelve hours is the difference between a bad day and the other kind.','Hector Salas',10,'ADVANCED','English',40,'/covers/twelve-hours-in-the-desert.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(84,'BOOK','Up, Up and Over the Orchard','The balloon comes down in the orchard every September, and this year Bea is finally tall enough to be allowed in the basket.','Sam Okonkwo',6,'BEGINNER','English',17,'/covers/up-up-and-over-the-orchard.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(85,'BOOK','Whale Fall','When a whale dies it sinks three thousand metres, and what happens next feeds a city on the sea floor for fifty years.','Dr. Yuki Tanabe',10,'ADVANCED','English',34,'/covers/whale-fall.svg',NULL,NULL,2,'2026-11-04 18:13:37'),(86,'BOOK','Where the Wild Beans Grow','Class 3 plant forty beans in forty cups. Thirty-nine behave themselves. This is the story of the fortieth, which went sideways on purpose.','Ada Rennick',7,'BEGINNER','English',21,'/covers/where-the-wild-beans-grow.svg',NULL,NULL,2,'2026-11-04 18:13:37');
