  `decision_by` bigint DEFAULT NULL,
  `request_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `decision_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `content_id` (`content_id`),
